"„Die Mauer hält die Monster draußen. Solange du drinnen bist, bist du sicher.“": "« Le rempart garde les monstres dehors. Tant que tu es dedans, tu es en sécurité. »",
"„Die Wildschweine fressen mir die Rüben weg. Wenn du welche siehst, jag sie!“": "« Les sangliers me mangent mes navets. Si tu en vois, chasse-les ! »",
"„Hast du schon mal einen Drachen gesehen? Lian sagt, am Feuerberg gibt es welche.“": "« Tu as déjà vu un dragon ? Lian dit qu'il y en a au Mont de Feu. »",
"„Früher war Kazehana eine ruhige Stadt. Dann kamen die Steine.“": "« Autrefois, Kazehana était une ville tranquille. Puis les pierres sont arrivées. »",
"„Jeder Stein hat seine eigene Seele. Und jeder lässt etwas anderes zurück.“": "« Chaque pierre a sa propre âme. Et chacune laisse quelque chose de différent. »",
