"Stadt · sicherer Ort": "Ville · lieu sûr",
"Lager · sicherer Ort": "Camp · lieu sûr",
"Die große Stadt Kazehana mit den grünen Sonnenwiesen.": "La grande ville de Kazehana et ses verts Prés ensoleillés.",
"Dichter Nadelwald mit Banditen, Spinnen und Bären. Spinnenhöhle und Banditenkeller.": "Forêt de conifères dense avec bandits, araignées et ours. Grotte des araignées et Cave des bandits.",
"Staubiges Tal der Orks und Skorpione. Orkfestung.": "Vallée poussiéreuse des orcs et scorpions. Forteresse orque.",
"Graue Aschenebene mit Ogern und Dämonen. Totengruft.": "Plaine de cendres grise avec ogres et démons. Crypte des morts.",
"Eisige Gipfel mit Eiswölfen, Yetis und Frostgeistern. Eisgrotte.": "Pics glacés avec loups de glace, yétis et esprits du givre. Grotte de glace.",
"Nebliges Moor voller Untoter, Hexen und Ghule.": "Marais brumeux plein de morts-vivants, sorcières et goules.",
"Schwarzer Basalt und Lavaflüsse, Golems, Feuerdämonen und Drachen. Drachenhort.": "Basalte noir et fleuves de lave, golems, démons de feu et dragons. Repaire du dragon.",
"Du wirbelst um dich selbst, triffst alle Gegner im Umkreis und betäubst sie kurz.": "Tu tournoies sur toi-même, frappes tous les ennemis autour et les étourdis brièvement.",
"Buff: Blitze zucken um dich. Mehr Angriffstempo und Lauftempo.": "Buff : des éclairs crépitent autour de toi. Plus de vitesse d'attaque et de course.",
"Erdbeben": "Séisme",
"Du stampfst auf und der Boden bebt: Alle Gegner um dich werden {0} s betäubt.": "Tu frappes du pied et le sol tremble : tous les ennemis autour sont étourdis {0} s.",
"Starker Körper": "Corps robuste",
"Buff: Dein Körper wird hart wie Stein. Mehr Verteidigung und weniger erlittener Schaden.": "Buff : ton corps devient dur comme la pierre. Plus de défense et moins de dégâts subis.",
"Geistesschlag": "Frappe spirituelle",
"Ein gebündelter Schlag mit voller Kraft auf ein einzelnes Ziel. Sehr hoher Schaden.": "Un coup concentré de toute ta force sur une seule cible. Dégâts très élevés.",
"Kriegsschrei": "Cri de guerre",
"Ein Schrei, der Gegner lähmt: Sie werden langsamer und nehmen mehr Schaden.": "Un cri qui paralyse les ennemis : ils ralentissent et subissent plus de dégâts.",
"Du drehst dich mit beiden Dolchen und triffst alle Gegner um dich.": "Tu tournoies avec tes deux dagues et frappes tous les ennemis autour de toi.",
"Schattensprung": "Saut d'ombre",
"Du springst durch die Schatten nach vorn und schneidest alles auf dem Weg.": "Tu bondis en avant à travers les ombres et tranches tout sur ton passage.",
"Lähmende Klinge": "Lame paralysante",
"Ein Stich in die Sehnen: Das Ziel ist {0} s betäubt und {1} s vergiftet.": "Un coup dans les tendons : la cible est étourdie {0} s et empoisonnée {1} s.",
"Schattenmantel": "Manteau d'ombre",
"Buff: Schatten hüllen dich ein. Mehr Ausweichen und mehr kritische Treffer.": "Buff : les ombres t'enveloppent. Plus d'esquive et plus de coups critiques.",
"Buff: Drachenkraft fließt in dich. Mehr Angriff und mehr Fertigkeitsschaden.": "Buff : la force du dragon coule en toi. Plus d'attaque et de dégâts de compétence.",
"Geisterfaust": "Poing spirituel",
"Eine Faust aus Geisterkraft trifft ein Ziel und betäubt es {0} s.": "Un poing de force spirituelle frappe une cible et l'étourdit {0} s.",
"Windfessel": "Entrave du vent",
"Wirbelnder Wind fesselt Gegner um dich: Sie werden langsamer und verwundbar.": "Un vent tourbillonnant entrave les ennemis autour de toi : ils ralentissent et deviennent vulnérables.",
"Segen": "Bénédiction",
"Buff: Weniger erlittener Schaden, Leben regeneriert sich, mehr kritische Treffer.": "Buff : moins de dégâts subis, PV régénérés, plus de coups critiques.",
"Heilung": "Soin",
"Heilt einen Teil deines Lebens und gibt dir danach mehr Angriff.": "Soigne une partie de tes PV, puis te donne plus d'attaque.",
