"Wolfsplage": "Fléau des loups",
"Die Wölfe werden mutiger. Dünne das Rudel aus, ehe sie das Tor erreichen.": "Les loups s'enhardissent. Éclaircis la meute avant qu'ils n'atteignent la porte.",
"Verirrte Hirsche": "Cerfs égarés",
"Der Alpha": "L'Alpha",
"Hinter den Wölfen stehen ihre Anführer, die Alpha-Wölfe. Ohne sie zerfällt das Rudel.": "Derrière les loups se tiennent leurs chefs, les loups alpha. Sans eux, la meute se disperse.",
"Keiler in den Rüben": "Sangliers dans les navets",
"Stein der Wut": "Pierre de la colère",
