"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "À peine les chiens partis, les renards rôdent autour des étables. Chasse-les vers les prairies",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "Les sangliers dévorent la récolte des paysans. Un hiver sans provisions serait notre fin",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "Au bord des prairies brille une pierre de rage. Sa fureur rend les bêtes folles – brise-la",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "Heureusement que Bao t'envoie. Des bandits attaquent chaque marchand sur le chemin forestier. Chasse-les",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "Les sangliers d'ici ont des épines au lieu de soies. Ils déchirent nos pièges – et les trappeurs",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "Au fond de la forêt, des araignées géantes tissent leurs toiles sur les chemins. Brûle-les s'il le faut",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "Au milieu de la forêt pousse une pierre d'épines. Ses ronces étouffent chaque arbre. Détruis-la",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "Hagen t'envoie ? Alors viens, les orques sont déjà devant nos palissades. Affaiblis leur armée",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "Les orques tiennent des hyènes comme des chiens et les lâchent sur nos éclaireurs. Élimine la meute",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "Idris t'envoie ? Les dieux sont bons avec Sahra. Les cobras guettent à chaque point d'eau",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "Tu entends ce cliquetis ? Des serpents à sonnette. Des centaines. Les caravanes n'osent plus partir",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "Sur le pic de givre, on a vu des yétis grands comme des maisons. Rapporte leurs peaux comme preuve",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "Les mammouths sont enragés depuis que le froid ne cède plus. Ils piétinent nos cabanes à provisions",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Là où se dresse la pierre du silence, chaque chant se tait. Ramène le son sur le sommet",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "La dernière et la plus puissante de toutes les pierres d'âme. Détruis-la et les pierres cesseront de croître",
