"Nachthirsche rennen mit leuchtenden Geweihen gegen unsere Zäune, als jage sie etwas. Halte sie auf": "Des cerfs nocturnes aux bois luisants foncent sur nos clôtures, comme si quelque chose les chassait. Arrête-les",
"Die Leitwölfe": "Les chefs de meute",
"Jedes Nebelrudel folgt einem Nachtleitwolf. Ohne ihn zerstreut sich das Rudel im Dunst": "Chaque meute des brumes suit un chef nocturne. Sans lui, la meute se disperse dans la brume",
